import re

TITLE = re.compile(r"^List of available plugins:\s*$")
OPTION = re.compile(r"^  (?P<option>--[\w-]+)(?:\s+(?P<argument>[<\[@]\S*(?: \S+)*?))?(?:\s{2,}(?P<description>\S.*?))?\s*$")
CONT = re.compile(r"^ {3,}(?P<text>\S.*?)\s*$")
FORM = re.compile(r"^  (?P<form>\S+)(?:\s+(?P<description>\S.*?))?\s*$")
PROSE = re.compile(r"^(?P<text>[A-Za-z].*?)\s*$")


def parse(lines):
    skip, plugins, plugin_lines = [], [], []
    forms, form_lines, notes, note_lines = [], [], [], []
    cur, mode = None, "plugins"
    for i, ln in enumerate(lines):
        if not ln.strip():
            continue
        if TITLE.match(ln):
            skip.append(i); mode = "plugins"; continue
        m = OPTION.match(ln)
        if m and mode == "plugins":
            cur = {"option": m.group("option"), "argument": m.group("argument") or "",
                   "description": m.group("description") or ""}
            plugins.append(cur); plugin_lines.append(i); continue
        m = CONT.match(ln)
        if m and cur is not None:
            cur["description"] = (cur["description"] + " " + m.group("text")).strip()
            (plugin_lines if mode == "plugins" else form_lines).append(i); continue
        m = PROSE.match(ln)
        if m:
            mode = "footer"; cur = None
            notes.append(m.group("text")); note_lines.append(i); continue
        m = FORM.match(ln)
        if m and mode == "footer":
            cur = {"form": m.group("form"), "description": m.group("description") or ""}
            forms.append(cur); form_lines.append(i); continue
    blocks = [{"name": "plugins", "kind": "table", "lines": plugin_lines, "records": plugins}]
    if notes:
        blocks.append({"name": "notes", "kind": "kv", "lines": note_lines,
                       "records": [{"pattern-list": " ".join(notes)}]})
    if forms:
        blocks.append({"name": "pattern-list forms", "kind": "table", "lines": form_lines, "records": forms})
    return {"blocks": blocks, "skip": skip}
